const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',story:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 0 1 19 0Z"/><path d="M7 9h10M7 13h7"/>',tasks:'<path d="m3 12 4 0 3-8 4 16 3-8h4"/>',recordings:'<path d="M4 5h16v15H4zM8 2v6m8-6v6M4 10h16M8 14h3m3 0h3"/>',profile:'<path d="M5 3h14v18H5zM8 8h8m-8 4h8m-8 4h5"/>',eeg:'<path d="M2 12h3l2-5 3 10 3-12 3 9 2-2h4"/>',messages:'<path d="M4 5h16v11H9l-5 4z"/><path d="M8 9h8M8 12h5"/>'};
const svg=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.profile}</svg>`;
const state={name:'Jordan M.',age:'68',hand:'Right',answers:[],confirmed:false,summary:'',records:[],reminder:'Mention one activity that feels different.',checks:[false,false,false],shared:null,clinicianNote:'',role:'patient'};
const questions=['What feels different about your movement? Describe it in your own words.','When did you first notice this? Has it changed since then?','Which side or part of your body feels affected? It is okay if you are unsure.','How does this affect something you do in daily life?'];
const prompts=['For example, typing feels less fluid.','For example, about two weeks ago.','For example, my left hand, or both hands.','For example, fastening buttons takes more effort.'];
let current='dashboard',timer=null,remaining=10,phase='idle',left=[],right=[];let toastTimer;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function modal(html,setup){$('#modal-body').innerHTML=html;$('#modal').showModal();setup?.()}
$('.modal-close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
const go=k=>location.hash=k;const action=(label,k,extra='')=>`<button class="btn ${extra}" data-go="${k}">${label}<span>↗</span></button>`;
function header(eye,title,sub='',btn=''){return `<div class="page-header"><div><p class="eyebrow">${eye}</p><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>${btn}</div>`}
window.guideMsgs=window.guideMsgs||[];
function guideChatHTML(){return `<span class="small-label">ASK THE GUIDE</span><div class="guide-log" id="guide-log">${guideMsgs.map(m=>`<div class="guide-msg ${m.role==='user'?'me':''}"><small>${m.role==='user'?'YOU':'GUIDE'}</small>${esc(m.text)}</div>`).join('')}</div><div class="guide-input"><input id="guide-q" placeholder="Ask about the process, or how to describe things…" maxlength="500"><button class="btn" id="guide-send">Send ↗</button></div>`}
function summary(){return state.summary||state.answers.map((a,i)=>['What feels different','When it started','Side or body area','Effect on daily life'][i]+': '+a).join('\n\n')}
function stats(r){return sessionText(r)}
function render(){const clinician=state.role==='clinician';$('#nav').innerHTML=(clinician?[['dashboard','Inbox'],['profile','Shared profiles'],['eeg','EEG report & copilot']]:[['dashboard','Dashboard'],['story','My story'],['tasks','Movement session'],['recordings','Recordings'],['profile','Visit profile'],['messages','Messages']]).map(([k,t])=>`<a href="#${k}" class="nav-item ${current===k?'active':''}">${svg(k)}${t}</a>`).join('');$('#person-name').textContent=state.name;$('#breadcrumb').textContent=(clinician?'Clinician workspace':'Your space')+' / '+(clinician&&current==='dashboard'?'Inbox':{dashboard:'Dashboard',story:'My story',tasks:'Movement session',recordings:'Recordings',profile:'Visit profile',eeg:'EEG report & copilot',messages:'Messages'}[current]||'Dashboard');
 if(!$('#role-toggle')){const t=document.createElement('button');t.id='role-toggle';t.className='text-btn';$('.topbar').insertBefore(t,$('.demo-label'))}$('#role-toggle').textContent=clinician?'Switch to patient view ↗':'Clinician view ↗';$('#role-toggle').onclick=()=>{stopTask();state.role=clinician?'patient':'clinician';current='dashboard';location.hash='dashboard';render()};
 $('#main').innerHTML=clinician?clinicianPage():({dashboard:dashboard,story:story,tasks:tasks,recordings:recordings,profile:profile,messages:()=>window.messagesPage?messagesPage():''}[current]||dashboard)();
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));bind();}
function dashboard(){const n=Number(state.confirmed)+Number(state.records.some(r=>r.completed&&r.mode==='full'))+Number(!!state.shared);return `<header class="desk-heading"><div><p class="eyebrow">BEFORE THE APPOINTMENT</p><h1>Before your first visit.</h1></div><p class="desk-intro">Your words. A clearer starting point.</p></header><div class="desk-layout"><section class="account-sheet"><div class="sheet-index"><span>01 / YOUR ACCOUNT</span><span>${state.confirmed?'CONFIRMED BY YOU':state.answers.length?'IN PROGRESS':'NOT STARTED'}</span></div><div class="account-content"><span class="quote-mark" aria-hidden="true">“</span><h2>${state.answers.length?esc(state.answers[0]):'What feels different?'}</h2><p>${state.answers.length?'Review or update your account.':'Four questions to help you explain it.'}</p>${action(state.confirmed?'Read your account':state.answers.length?'Continue your account':'Start my story','story')}</div><div class="sheet-foot"><span>${state.confirmed?'Confirmed by you.':'You approve it before sharing.'}</span><span class="sheet-corner" aria-hidden="true">↗</span></div></section><aside class="desk-aside"><section class="identity-block"><div class="identity-title"><span class="identity-initial">${esc(state.name.charAt(0))}</span><div><p class="eyebrow">YOUR PROFILE</p><h2>${esc(state.name)}</h2></div></div><dl><div><dt>Age</dt><dd>${esc(state.age)||'Not added'}</dd></div><div><dt>Dominant hand</dt><dd>${esc(state.hand)}</dd></div></dl><button class="text-btn" id="profile-edit-shortcut">Edit details</button></section><section class="desk-note"><div class="note-heading"><h3>A note for later</h3><button id="edit-note" aria-label="Edit your reminder">Edit</button></div><p>${esc(state.reminder)}</p><span>ONLY FOR YOU</span></section>${state.clinicianNote?`<section class="clinician-margin"><p class="eyebrow">FROM YOUR CLINICIAN</p><p>${esc(state.clinicianNote)}</p></section>`:''}</aside><section class="desk-tasks"><div class="section-heading"><h2>Next steps</h2><span class="preparation-count">${n} / 3 ready</span></div>${[['02','Movement session',state.records.some(r=>r.completed&&r.mode==='full')?'Session recorded.':'Cued hand movement with the headset.','tasks',state.records.some(r=>r.completed&&r.mode==='full')],['03','Visit profile',state.shared?'Shared with your clinician.':'Review, then choose to share.','profile',!!state.shared]].map(([num,t,p,k,done])=>`<button class="desk-task" data-go="${k}"><span class="task-index">${num}</span><span><strong>${t}</strong><small>${p}</small></span><span class="task-link">${done?'Ready':'Open'} <i>↗</i></span></button>`).join('')}<p class="desk-footnote">Appointment preparation · No diagnosis</p></section></div>`}
function story(){const idx=state.answers.length;return header('MY STORY','Let’s put it into words.','The guide asks four questions. You review every word before sharing.')+`<div class="two-col"><section class="panel"><div class="agent-intro"><span class="agent-symbol">✳</span><span><b>Your conversation guide</b><small>${window.AI&&window.AI.connected?(window.AI.llm?"AI guide connected · drafts a summary for your review":"AI template mode · no API key set"):"Scripted guide · No AI service connected"}</small></span></div><div class="conversation" id="conversation">${state.answers.map((a,i)=>`<div class="bubble"><small>GUIDE</small>${questions[i]}</div><div class="bubble user"><small>YOU</small>${esc(a)}</div>`).join('')}<div class="bubble"><small>GUIDE</small>${idx<4?questions[idx]:(window.AI&&window.AI.connected?'Thank you. I have drafted an account from your answers — it is in the panel on the right. Please check every word and change anything that is not your wording.':'Thank you. I have grouped your answers by topic, keeping your wording. Please check the summary and change anything that is inaccurate.')}</div></div>${idx<4?`<form id="answer-form"><label class="small-label" for="answer">YOUR WORDS · ${idx+1} OF 4</label><div class="composer"><textarea id="answer" placeholder="${prompts[idx]}" required maxlength="3000"></textarea><button class="btn" type="submit">Continue ↗</button></div></form><button class="inline-example" id="example">Use a fictional example for this step</button>`:`<button class="text-btn" id="restart-story">Start these questions again</button>`}</section><aside class="panel"><span class="small-label">YOUR ACCOUNT</span><h2 style="margin-top:10px">Does this sound like you?</h2><span class="status ${state.confirmed?'confirmed':''}">${state.confirmed?'Confirmed by you':'Waiting for your review'}</span>${idx?`<p class="summary-body">${esc(summary())}</p>${idx===4?`<p class="hint">${state.aiSource==='ai'?'Drafted by your AI guide from your own answers — check every word before confirming. You confirm it, not the AI.':'Grouped from your answers. Check every word.'}</p>`:''}`:`<p class="hint">Your answers will appear here, organized into a short account of your concern.</p>`}${idx===4?`<div class="actions"><button class="btn blue" id="confirm-story">${state.confirmed?'Continue to tasks':'Yes, this sounds right'}</button><button class="btn secondary" id="edit-summary">Edit wording</button></div>${idx===4?guideChatHTML():''}`:''}<p class="hint">The guide does not infer a condition or fill in missing symptoms. Your answers are kept as you wrote them, without a clinical interpretation.</p></aside></div>`}
function tasks(){return sessionPage()}
function stage(){if(phase==='idle')return `<span class="small-label">GUIDED FINGER TAPPING</span><span class="key">A</span><h2>Left hand first.</h2><p>When you are ready, tap A with your left index finger.</p><button class="btn blue" id="start-task">Begin left hand</button>`;if(phase==='between')return `<span class="small-label">LEFT HAND COMPLETE</span><span class="key">L</span><h2>Now your right hand.</h2><p>Take a moment. The next activity uses the L key.</p><button class="btn blue" id="next-hand">Begin right hand</button>`;if(phase==='done')return `<span class="small-label">RECORDING COMPLETE</span><h2 style="margin-top:20px">Your activity is recorded.</h2><p>Left ${left.length} taps · Right ${right.length} taps</p><div class="notice" id="task-feedback" style="margin-top:16px">The recording assistant is reviewing your taps…</div>${action('Review the recording','recordings')}<button class="text-btn" id="again" style="margin-top:18px">Try another recording</button>`;return `<span class="small-label">${phase==='left'?'LEFT':'RIGHT'} HAND · ${phase==='left'?'A':'L'} KEY</span><span class="timer" id="countdown">${remaining}</span><h2>Tap at a comfortable pace.</h2><p><span id="tap-count">${phase==='left'?left.length:right.length}</span> taps recorded</p><button class="tap-target" id="tap">Tap here instead</button><button class="text-btn" id="stop-task" style="margin-top:18px">Stop and discard</button>`}
function start(hand){window._fbFetched=false;phase=hand;remaining=10;const start=performance.now();window.tapStart=start;updateStage();timer=setInterval(()=>{remaining=Math.max(0,Math.ceil(10-(performance.now()-start)/1000));if($('#countdown'))$('#countdown').textContent=remaining;if(!remaining){clearInterval(timer);timer=null;if(hand==='left')phase='between';else{phase='done';state.records.unshift({id:Date.now(),label:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}),left:[...left],right:[...right],seconds:10});state.checks[1]=true}updateStage()}},100)}
function updateStage(){$('#task-stage').innerHTML=stage();bindTask()}
function tap(){if(phase!=='left'&&phase!=='right')return;(phase==='left'?left:right).push(Math.round(performance.now()-window.tapStart));$('#tap-count').textContent=phase==='left'?left.length:right.length}
function stopTask(){if(window.sessionLeave)sessionLeave();if(timer)clearInterval(timer);timer=null;phase='idle';left=[];right=[]}
function bindTask(){if($('#start-task'))$('#start-task').onclick=()=>{left=[];right=[];start('left')};if($('#next-hand'))$('#next-hand').onclick=()=>start('right');if($('#tap'))$('#tap').onclick=tap;if($('#stop-task'))$('#stop-task').onclick=()=>{stopTask();updateStage();toast('Incomplete recording discarded')};if($('#again'))$('#again').onclick=()=>{stopTask();updateStage()}
if($('#task-feedback')&&!window._fbFetched){window._fbFetched=true;aiCall('/api/task/feedback',{left,right,seconds:10}).then(j=>{const el=$('#task-feedback');if(!el)return;el.innerHTML='<b>Recording assistant</b> · '+(j.feedback?esc(j.feedback)+(j.source==='llm'?'':' <small>(template mode — set ANTHROPIC_API_KEY for AI feedback)</small>'):'Assistant unavailable — your counts are saved with the recording.')})}}
window.addEventListener('keydown',e=>{if(current!=='tasks'||state.role!=='patient'||!['left','right'].includes(phase)||e.repeat||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if(e.key.toLowerCase()===(phase==='left'?'a':'l')){e.preventDefault();tap()}});
function recordings(){return header('RECORDINGS','Your movement recordings.','A record of what you did, with the context needed to interpret it.',action('New recording','tasks'))+`<section class="panel">${state.records.length?state.records.map((r,i)=>`<div class="record-row"><div><h3>${r.mode==='full'?'Movement session':'Rehearsal'} ${state.records.length-i}</h3><p>Today at ${esc(r.label)} · ${r.headset?'With headset':'No headset'}${r.camera?' · Camera check':''}</p></div><span class="record-values">${r.completed?'Complete':'Stopped'} · ${r.cues_shown}/${r.total} cues</span><button class="text-btn" data-record="${r.id}">View details</button></div>`).join(''):`<div class="empty"><h3>A place for your recordings.</h3><p>Complete a guided task to see its measurements here.</p>${action('Explore movement tasks','tasks')}</div>`}<p class="hint">Repeated recordings may help investigate consistency. Recordings are not compared against a healthy range.</p></section>`}
function reportContent(p){return `<div class="report-header"><div><span class="small-label">PRE-VISIT HEALTH PROFILE</span><div class="report-title">${esc(p.name)}</div><p>Age ${esc(p.age)||'not provided'} · Dominant hand: ${esc(p.hand)}</p></div><span class="status confirmed">Patient confirmed</span></div><section class="report-section"><span class="small-label">PATIENT-REPORTED CONCERN</span><h3>In the patient’s own words</h3><p>${esc(p.summary)}</p></section><section class="report-section"><span class="small-label">MEASURED ACTIVITY</span><h3>Cued movement session</h3><p style="white-space:pre-line">${p.records.length?esc(stats(p.records[0])):'No session included.'}</p><p class="hint">EEG results are not part of this profile. No clinical interpretation included.</p></section><section class="report-section"><h3>About this profile</h3><p>The patient reviewed the account above. The guide groups their answers by topic. It adds no diagnosis. Report preparation and clinical benefit require evaluation.</p></section>`}
function snapshot(){return {name:state.name,age:state.age,hand:state.hand,summary:summary(),records:JSON.parse(JSON.stringify(state.records.filter(r=>r.completed&&r.mode==='full').slice(0,1))),sharedAt:new Date().toISOString()}}
function profile(){return header('VISIT PROFILE','Your story, ready to review.','You choose when your profile is ready and who can see it.')+`<div class="two-col"><section class="panel">${state.confirmed?reportContent(snapshot()):`<div class="empty"><h3>Your story comes first.</h3><p>Answer the four questions and confirm that the summary sounds right before preparing your profile.</p>${action('Continue my story','story')}</div>`}</section><aside class="panel"><span class="small-label">YOUR CHOICE</span><h2 style="margin:10px 0 16px">Share with consent.</h2><p style="font-size:14px">Review your account and the measurements you want to discuss.</p><div class="actions"><button class="btn blue" id="share" ${state.confirmed?'':'disabled'}>${state.shared?'Update shared profile':'Review & share'} ↗</button><button class="btn secondary" id="download" ${state.confirmed?'':'disabled'}>Download report</button></div>${state.shared?`<p class="hint">A snapshot is shared with your clinician. Later changes stay private until you share again.</p><button class="text-btn" id="revoke">Withdraw access</button>`:''}</aside></div>`}
function clinicianPage(){if(current==='eeg')return header('CLINICIAN WORKSPACE · NEUROSYM','EEG report & copilot.','The model report for a recording, and a copilot that can only cite its numbers.')+(window.copilotSection?copilotSection():'');if(current==='dashboard')return header('CLINICIAN WORKSPACE','Inbox.','Messages, shared profiles and session updates from your patients.')+(window.inboxSection?inboxSection():'')+(window.copilotSection?`<header class="cp-section-head"><p class="eyebrow">NEUROSYM · EEG</p><h2>Recording report & copilot</h2></header>`+copilotSection():'');return clinicianProfilePage()}
function clinicianProfilePage(){return header('CLINICIAN WORKSPACE',current==='profile'?'Patient-shared profile':'A clearer first conversation.','Only the profile the patient chose to share appears here.')+(state.shared?`<div class="two-col"><section class="panel">${reportContent(state.shared)}</section><aside class="panel"><span class="small-label">PATIENT-SHARED SNAPSHOT</span><h2 style="margin-top:10px">Review context</h2><div class="task-status"><span>Source</span><span>Patient confirmed</span></div><div class="task-status"><span>EEG</span><span>Not included</span></div><div class="task-status"><span>Clinical interpretation</span><span>Not generated</span></div><div class="field" style="margin-top:24px"><label for="clinician-note">Note for the patient</label><textarea id="clinician-note" placeholder="A short preparation note…"></textarea></div><button class="btn" id="save-clinician-note">Send note</button><p class="hint">Sent to the patient’s messages and shown on their dashboard.</p></aside></div>`:`<section class="panel"><div class="empty">${window.SL&&SL.withdrawn()?`<h3>Access withdrawn by the patient.</h3><p>The patient withdrew access to their visit profile on ${SL.withdrawn()}. It reappears here only if they choose to share again.</p>`:`<h3>No profile shared yet.</h3><p>The patient needs to confirm their story and consent to sharing before a profile appears here.</p>`}<button class="btn" id="back-patient">Open patient workspace ↗</button></div></section>`)}
function bind(){if($('#profile-edit-shortcut'))$('#profile-edit-shortcut').onclick=()=>$('#edit-person').click();document.querySelectorAll('[data-check]').forEach(c=>c.onchange=()=>state.checks[+c.dataset.check]=c.checked);if($('#future'))$('#future').onclick=()=>modal(`<span class="eyebrow">FUTURE RESEARCH</span><h2>Everyday movements, over time.</h2><p>We want to investigate reliable EEG and movement measurements during ordinary activities. Today, this uses a controlled keyboard task.</p><p class="hint">Real-world artifact handling, sensor comfort, and clinical value require validation.</p>`);if($('#edit-note'))$('#edit-note').onclick=()=>modal(`<h2>A note to myself</h2><div class="field" style="margin-top:20px"><label for="note">Your reminder</label><textarea id="note" maxlength="180">${esc(state.reminder)}</textarea></div><button class="btn" id="save-note">Save note</button>`,()=>$('#save-note').onclick=()=>{state.reminder=$('#note').value;$('#modal').close();render()});
if($('#answer-form'))$('#answer-form').onsubmit=e=>{e.preventDefault();const v=$('#answer').value.trim();if(!v)return;state.answers.push(v);state.confirmed=false;state.summary='';render();$('#conversation').scrollTop=$('#conversation').scrollHeight};if($('#example'))$('#example').onclick=()=>{$('#answer').value=['Typing feels less fluid than usual.','I first noticed it about two weeks ago. It comes and goes.','Mostly my left hand, but I am not sure.','Fastening small buttons seems to take more effort.'][state.answers.length];$('#answer').focus()};
if(current==='story'&&state.answers.length===4&&!state.summary&&!state.aiTried&&!state.aiDrafting){state.aiTried=true;state.aiDrafting=true;aiCall('/api/story/summary',{answers:state.answers}).then(j=>{state.aiDrafting=false;if(j&&j.summary){state.summary=j.summary;state.aiSource=(j.source==='llm'?'ai':'template')}else{state.aiSource='template'}render()});}
if($('#confirm-story'))$('#confirm-story').onclick=()=>{if(state.confirmed){go('tasks');return}state.confirmed=true;state.checks[0]=true;render();toast('Your account is confirmed. You can edit it at any time.')};if($('#edit-summary'))$('#edit-summary').onclick=()=>modal(`<h2>Your wording</h2><div class="field" style="margin-top:20px"><label for="summary-edit">Edit your account</label><textarea id="summary-edit" style="min-height:260px">${esc(summary())}</textarea></div><button class="btn" id="save-summary">Save for review</button>`,()=>$('#save-summary').onclick=()=>{const v=$('#summary-edit').value.trim();if(!v)return;state.summary=v;state.confirmed=false;$('#modal').close();render()});if($('#guide-send'))$('#guide-send').onclick=async()=>{const q=$('#guide-q').value.trim();if(!q)return;guideMsgs.push({role:'user',text:q});render();const j=await aiCall('/api/story/chat',{answers:state.answers,messages:guideMsgs.slice(-8)});guideMsgs.push({role:'guide',text:(j&&j.reply)||'The guide is unavailable right now. The steps above still work the same.'});render()};
if($('#guide-q'))$('#guide-q').onkeydown=e=>{if(e.key==='Enter'){$('#guide-send').click()}};
if($('#restart-story'))$('#restart-story').onclick=()=>modal('<h2>Start a new account?</h2><p class="hint">This clears your current answers. A previously shared snapshot stays unchanged until you update or withdraw it.</p><button class="btn" id="restart-confirm">Clear answers and start</button>',()=>$('#restart-confirm').onclick=()=>{state.answers=[];state.summary='';state.confirmed=false;state.checks[0]=false;$('#modal').close();render()});
bindTask();if($('#squeeze'))$('#squeeze').onclick=()=>modal('<h2>Gentle squeeze is planned.</h2><p class="hint">This task needs suitable force or movement sensing. That hardware is not connected yet, so squeeze results are not available.</p>');
document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>{const r=state.records.find(x=>x.id===+b.dataset.record);modal(`<h2>Session details</h2><p class="summary-body">${esc(stats(r))}</p><p class="hint">EEG results are reviewed by the care team and are not shown here. The camera check counts hand movement only and does not use the EEG.</p><button class="btn" id="download-record">Download session summary</button>`,()=>$('#download-record').onclick=()=>download('neurobridge-session.json',JSON.stringify(r,null,2),'application/json'))});
if($('#download'))$('#download').onclick=()=>{const p=snapshot();download('neurobridge-visit-profile.txt',`NEUROBRIDGE — PRE-VISIT PROFILE\n${p.name}\nAge: ${p.age}\nDominant hand: ${p.hand}\n\nPATIENT-CONFIRMED ACCOUNT\n${p.summary}\n\nMEASURED ACTIVITY\n${p.records.length?stats(p.records[0]):'No task included.'}\n\nNo clinical interpretation or diagnosis generated.`, 'text/plain');toast('Report downloaded')};
if($('#share'))$('#share').onclick=()=>modal(`<span class="eyebrow">REVIEW YOUR CHOICE</span><h2>Share this profile?</h2><p class="hint">Recipient: Your clinician’s workspace.<br>Purpose: appointment preparation.<br>Includes: basic profile, confirmed account, and a summary of your latest completed movement session if there is one (no EEG results).</p><label style="display:flex;gap:12px;margin:25px 0"><input type="checkbox" id="consent"><span>I consent to sharing this snapshot with my clinician.</span></label><button class="btn blue" id="confirm-share" disabled>Share with clinician</button>`,()=>{$('#consent').onchange=()=>$('#confirm-share').disabled=!$('#consent').checked;$('#confirm-share').onclick=()=>{const prev=[state.shared,state.checks[2]];state.shared=snapshot();state.checks[2]=true;$('#modal').close();render();if(window.SL)SL.share(state.shared,()=>{state.shared=prev[0];state.checks[2]=prev[1];render()});else toast('Shared with your clinician')}});
if($('#revoke'))$('#revoke').onclick=()=>{const prev=[state.shared,state.checks[2]];state.shared=null;state.checks[2]=false;render();if(window.SL)SL.withdraw(()=>{state.shared=prev[0];state.checks[2]=prev[1];render()});else toast('Clinician access withdrawn')};if($('#back-patient'))$('#back-patient').onclick=()=>{state.role='patient';current='dashboard';render()};if($('#save-clinician-note'))$('#save-clinician-note').onclick=()=>{const v=$('#clinician-note').value.trim();if(!v)return;if(window.SL)SL.note(v);$('#clinician-note').value='';toast('Note sent to the patient')};if(state.role==='clinician'&&window.copilotBind)copilotBind();if(current==='tasks'&&state.role==='patient'&&window.sessionBind)sessionBind();if(window.sharedBind)sharedBind();}
function download(name,body,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#edit-person').onclick=()=>modal(`<h2>Your basic profile</h2><div class="field"><label for="name">Preferred name</label><input id="name" value="${esc(state.name)}" maxlength="80"></div><div class="field"><label for="age">Age (optional)</label><input id="age" type="number" min="1" max="120" value="${esc(state.age)}"></div><div class="field"><label for="hand">Dominant hand</label><select id="hand">${['Right','Left','Both','Prefer not to say'].map(h=>`<option ${state.hand===h?'selected':''}>${h}</option>`).join('')}</select></div><button class="btn" id="save-person">Save profile</button>`,()=>$('#save-person').onclick=()=>{state.name=$('#name').value.trim()||'Your profile';state.age=$('#age').value;state.hand=$('#hand').value;$('#modal').close();render()});
window.addEventListener('hashchange',()=>{stopTask();current=location.hash.slice(1)||'dashboard';render();window.scrollTo(0,0)});current=location.hash.slice(1)||'dashboard';render();
